import type { OAuthHelpers } from "@cloudflare/workers-oauth-provider";

// Bindings and vars come from worker-configuration.d.ts, generated by
// `wrangler types` (run as part of `npm run typecheck`). This file adds what
// wrangler cannot see: secrets, production-only settings, and the helper
// object that OAuthProvider injects.
interface ExtraEnv {
  OAUTH_PROVIDER: OAuthHelpers;
  /** Secret: HMAC key for confirmation state, at least 32 characters. */
  CONFIRMATION_SECRET: string;
  GITHUB_CLIENT_ID?: string;
  /** Secret. */
  GITHUB_CLIENT_SECRET?: string;
}

declare global {
  interface Env extends ExtraEnv {}
  namespace Cloudflare {
    interface Env extends ExtraEnv {}
  }
}

export {};
